// Accepts ANY TradingView body. Never drops a signal: if it can't be parsed, the raw text is shown.
const KEY = 'change-me';
const ACT = {'1':'BUY CALLS','-1':'BUY PUTS','2':'SELL HALF CALLS','-2':'SELL HALF PUTS','3':'EXIT CALLS','-3':'EXIT PUTS'};
const STR = {'1':'S1 ORB 30m','2':'S2 SWEEP REVERSAL','3':'S3 VWAP','4':'S4 OPENING DRIVE','5':'S5 TREND PULLBACK'};
const store = $getWorkflowStaticData('global');
store.signals = store.signals || [];
for (const item of $input.all()) {
  let b = item.json.body;
  if ((b == null || (typeof b === 'object' && Object.keys(b).length === 0)) && item.binary && item.binary.data) {
    b = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
  }
  if (b == null) continue;
  let raw = typeof b === 'string' ? b : JSON.stringify(b);
  if (typeof b === 'string') {
    const cleaned = b.replace(/\[\[[^\]]*\]\]/g, 'null').replace(/\{\{[^}]*\}\}/g, 'null').replace(/\bNaN\b/g, 'null');
    try { b = JSON.parse(cleaned); } catch (e) { b = { ticker: '?', action: 'RAW', note: raw.slice(0, 300) }; }
  }
  if (b.src === 'cc-ac') {
    b.action = b.code == null ? 'SIGNAL (see chart)' : (ACT[String(Math.round(b.code))] || ('code ' + b.code));
    b.strategy = b.strat == null ? '' : (STR[String(Math.round(b.strat))] || '');
    delete b.code; delete b.strat; delete b.src;
  } else if (b.key !== undefined && b.key !== KEY) {
    b.note = 'KEY MISMATCH - check Webhook key in CC-Multi settings';
  }
  if (typeof b.rvol === 'number') b.rvol = Math.round(b.rvol * 10) / 10;
  delete b.key;
  b.received = new Date().toISOString();
  store.signals.unshift(b);
}
store.signals = store.signals.slice(0, 500);
return [{ json: { ok: true, stored: store.signals.length } }];

const s = ($getWorkflowStaticData('global').signals || []);
const esc = v => String(v ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const col = a => /BUY CALLS/.test(a) ? '#16a34a' : /BUY PUTS/.test(a) ? '#dc2626' : /HALF/.test(a) ? '#f59e0b' : '#6b7280';
const rows = s.map(x => `<tr><td>${esc(x.time)}</td><td><b>${esc(x.ticker)}</b></td><td style="color:#fff;background:${col(x.action)}">${esc(x.action)}</td><td>${esc(x.strategy)}</td><td>${esc(x.price)}</td><td>${esc(x.stop)}</td><td>${esc(x.t1)}</td><td>${esc(x.t2)}</td><td>${esc(x.rvol)}x</td><td style="color:#9ca3af">${esc(x.note)}</td></tr>`).join('');
const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="10"><title>CC Signals</title><style>body{font-family:system-ui;background:#0b0f14;color:#e5e7eb;margin:16px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:6px 8px;border-bottom:1px solid #1f2937;text-align:left}th{color:#9ca3af}</style></head><body><h2>Chart Commander signals</h2><p style="color:#9ca3af">Auto-refreshes every 10s. Newest first. Times ET.</p><table><tr><th>Time</th><th>Ticker</th><th>Action</th><th>Strategy</th><th>Price</th><th>Stop</th><th>T1</th><th>T2</th><th>Vol</th><th>Note</th></tr>${rows || '<tr><td colspan=10>No signals yet</td></tr>'}</table></body></html>`;
return [{ json: { html } }];
